class Solution {
public:
    int numOfArrays(int n, int m, int k) {
        const int MOD = 1000000007;
        // dp[j][c]: number of ways to build prefix so far
        // j = current maximum (0 = virtual, no element placed yet)
        // c = search cost so far
        vector<vector<long long>> dp(m + 1, vector<long long>(k + 1, 0));
        dp[0][0] = 1;

        for (int pos = 0; pos < n; pos++) {
            vector<vector<long long>> ndp(m + 1, vector<long long>(k + 1, 0));
            for (int c = 0; c <= k; c++) {
                // Part 1: pick v in [1, j] - max stays j, cost stays c
                // There are j such choices
                for (int j = 1; j <= m; j++) {
                    ndp[j][c] = (ndp[j][c] + dp[j][c] * j) % MOD;
                }
                // Part 2: pick v in [j+1, m] - new max = v, cost = c+1
                // Use prefix sum: prefix = sum of dp[j'][c] for j' in [0, v-1]
                long long prefix = dp[0][c];
                for (int v = 1; v <= m; v++) {
                    if (c + 1 <= k) {
                        ndp[v][c + 1] = (ndp[v][c + 1] + prefix) % MOD;
                    }
                    prefix = (prefix + dp[v][c]) % MOD;
                }
            }
            dp = move(ndp);
        }

        long long ans = 0;
        for (int j = 1; j <= m; j++) {
            ans = (ans + dp[j][k]) % MOD;
        }
        return (int)ans;
    }
};
